```javascript
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture, uniform, time } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // 1. BUILD THE STAGE BACKDROP
  const group = new THREE.Group();

  // 2. CREATE TESSELLATED PLANE WITH DISPLACEMENT
  const planeGeom = new THREE.PlaneGeometry(7, 4, 64, 64);

  // Load textures asynchronously but prepare material synchronously
  const texturePromises = [];
  let colorMap = null;
  let depthMap = null;

  if (config.imageUrl) {
    texturePromises.push(
      ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
        colorMap = tex;
        colorMap.colorSpace = THREE.SRGBColorSpace;
      })
    );
  }

  if (config.depthMapUrl) {
    texturePromises.push(
      ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
        depthMap = tex;
      })
    );
  }

  // Create material with TSL nodes for displacement
  const displacementScale = uniform(0.15);
  const depthTexture = uniform(null);
  const colorTexture = uniform(null);

  const material = new MeshStandardNodeMaterial({
    color: 0xe8ecf2,
    roughness: 0.6,
    metalness: 0.2,
    emissive: 0x000000,
  });

  // Build TSL shader for displacement
  const positionNode = planeGeom.getAttribute('position');
  const normalizedUV = uv();

  // Displacement from depth map
  const displacementSampler = texture(depthTexture, normalizedUV);
  const displacedPosition = mix(
    positionNode,
    vec3(
      positionNode.x,
      positionNode.y,
      displacementSampler.r.mul(displacementScale)
    ),
    uniform(depthMap ? 1.0 : 0.0)
  );

  material.positionNode = displacedPosition;
  material.colorNode = texture(colorTexture, normalizedUV);

  const planeMesh = new THREE.Mesh(planeGeom, material);
  planeMesh.receiveShadow = true;
  planeMesh.castShadow = true;
  planeMesh.position.z = 0;

  group.add(planeMesh);

  // 3. ADD LIGHTING (key + rim for product shot aesthetic)
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1, 2, 3);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.width = 2048;
  keyLight.shadow.mapSize.height = 2048;
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(0xff2a38, 0.6);
  rimLight.position.set(-2, 1, -2);
  group.add(rimLight);

  const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
  group.add(ambientLight);

  // 4. INTERACTIVE BEHAVIOR
  const state = {
    isHovering: false,
    pressTimeline: null,
    hoverTimeline: null,
  };

  const handlers = {
    onHover() {
      if (state.isHovering) return;
      state.isHovering = true;

      if (state.hoverTimeline) state.hoverTimeline.kill();

      state.hoverTimeline = gsap.timeline();
      state.hoverTimeline.to(group.position, {
        y: group.position.y + 0.15,
        duration: 0.4,
        ease: 'power3.out',
      }, 0);

      state.hoverTimeline.to(group.scale, {
        x: 1.02,
        y: 1.02,
        z: 1.02,
        duration: 0.4,
        ease: 'power3.out',
      }, 0);
    },

    onHoverEnd() {
      state.isHovering = false;

      if (state.hoverTimeline) state.hoverTimeline.kill();

      state.hoverTimeline = gsap.timeline();
      state.hoverTimeline.to(group.position, {
        y: group.position.y - 0.15,
        duration: 0.6,
        ease: 'power4.out',
      }, 0);

      state.hoverTimeline.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.6,
        ease: 'power4.out',
      }, 0);
    },

    onClick() {
      if (state.pressTimeline) state.pressTimeline.kill();

      state.pressTimeline = gsap.timeline();
      state.pressTimeline.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });

      state.pressTimeline.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.3,
        ease: 'elastic.out',
      });

      // Emit navigation event
      ctx.emit('navigate', { to: 'hub-features' });
    },
  };

  // 5. RESOLVE TEXTURES AND UPDATE MATERIAL
  Promise.all(texturePromises).then(() => {
    if (colorMap) {
      colorTexture.value = colorMap;
      material.needsUpdate = true;
    }
    if (depthMap) {
      depthTexture.value = depthMap;
      material.needsUpdate = true;
    }
  });

  // 6. APPLY SCENE POSITION (adapter will override, but set locally for consistency)
  group.position.set(-1.25, 1.6, 0);

  // 7. SETUP CLEANUP
  const cleanupList = [];

  group.userData.handlers = handlers;
  group.userData.cleanup = () => {
    if (state.hoverTimeline) state.hoverTimeline.kill();
    if (state.pressTimeline) state.pressTimeline.kill();

    material.dispose();
    planeGeom.dispose();

    if (colorMap) colorMap.dispose();
    if (depthMap) depthMap.dispose();

    cleanupList.forEach((fn) => fn());
  };

  return group;
}
